@Configuration
public class SessionConfiguration {
    // In modern cloud-native architectures, we avoid sticky sessions entirely
    // by externalizing session state into a distributed Redis cluster using Spring Session.

    @Bean
    public ConfigureRedisHttpSession redisHttpSessionConfig() {
        // Configures HttpSession to transparently serialize attributes to Redis,
        // rendering backend nodes completely stateless and immune to sticky session risks.
        return new ConfigureRedisHttpSession();
    }
}
